import React, { useState } from "react";

export default function CorrectedDocument({ originalClauses, correctedDocument }) {
  const [view, setView] = useState("corrected"); // default show improved version

  return (
    <div className="mt-8 p-6 bg-white rounded-xl shadow-md border border-gray-200">
      <h2 className="text-2xl font-semibold text-gray-900 mb-4">
        📄 Corrected Document (AI-Reconstructed)
      </h2>

      {/* Toggle Buttons */}
      <div className="flex gap-4 mb-4">
        <button
          className={`px-4 py-2 rounded-lg font-medium ${
            view === "corrected"
              ? "bg-blue-600 text-white"
              : "bg-gray-200 text-gray-800"
          }`}
          onClick={() => setView("corrected")}
        >
          AI-Corrected Version
        </button>

        <button
          className={`px-4 py-2 rounded-lg font-medium ${
            view === "original"
              ? "bg-blue-600 text-white"
              : "bg-gray-200 text-gray-800"
          }`}
          onClick={() => setView("original")}
        >
          Original Document
        </button>
      </div>

      {/* Display Content */}
      <div className="whitespace-pre-wrap leading-relaxed bg-gray-50 p-4 rounded-lg border border-gray-300 text-gray-900">
        {view === "corrected" ? correctedDocument : originalClauses.join("\n\n")}
      </div>
    </div>
  );
}
